function validate([word]) {
  if (typeof word !== 'string' || word.length < 1 || word.length > 50) return 'word needs 1 to 50 letters.';
  if (!/^[abc]+$/.test(word)) return "word may contain only 'a', 'b' and 'c'.";
  return null;
}

