function addMinimum(word) {
  let blocks = 1;
  for (let i = 1; i < word.length; i++) {
    const startsNewBlock = word[i] <= word[i - 1];
    if (startsNewBlock) {
      blocks++;
    }
  }
  const fullLength = blocks * 3;
  return fullLength - word.length;
}

