function addMinimum(word) {
  // Find the fewest copies of "abc" that contain word as a subsequence.
  for (let copies = 1; ; copies++) {
    const target = 'abc'.repeat(copies);
    let matched = 0;
    for (let k = 0; k < target.length && matched < word.length; k++) {
      if (target[k] === word[matched]) matched++;
    }
    if (matched === word.length) return target.length - word.length;
  }
}

