function generate(rand, size) {
  const n = size === 'large' ? 30 + Math.floor(rand() * 21) : 1 + Math.floor(rand() * 8);
  const mode = rand();
  let word = '';
  for (let i = 0; i < n; i++) {
    if (mode < 0.3) {
      // Mostly in "abc" order, with an occasional missing letter.
      const letter = 'abc'[i % 3];
      word += rand() < 0.8 ? letter : 'abc'[Math.floor(rand() * 3)];
    } else if (mode < 0.45) {
      // Only 'b' and 'c', so many letters must open new blocks.
      word += 'bc'[Math.floor(rand() * 2)];
    } else {
      word += 'abc'[Math.floor(rand() * 3)];
    }
  }
  return [word];
}
